using System;using System.IO;using System.Linq;using NUnit.Framework;using UnityEngine;using IdleIntelligence.Core;
namespace IdleIntelligence.Tests {
 [Serializable]public sealed class ResearchStartV3Job{public string id,cause,previousArea,area,completionCause;public double startedAt,required,done,eventWork,remaining,minimumSeconds,minimumUntil,startingFraction;public int version;public long automaticOrdinal;public bool bypassed;}
 [Serializable]public sealed class ResearchStartV3Step{public string action;public bool allowed,same;public double at;public NumberData credits,data;public long gems,automaticCount;public int prestiges,axioms;public int[] levels;public ResearchStartV3Job[] jobs;}
 [Serializable]public sealed class ResearchStartV3Flow{public string name,mode;public bool prepared;public ResearchStartV3Step[] steps;}
 [Serializable]public sealed class ResearchStartV3Cases{public string sourceHash;public bool productionEnabled;public ResearchStartV3Flow[] flows;}
 public sealed class ItemSystemV3ResearchStartTests {
  static ResearchStartV3Cases Cases()=>JsonUtility.FromJson<ResearchStartV3Cases>(File.ReadAllText(Path.Combine(Application.dataPath,"IdleIntelligence/Tests/EditMode/ItemV3ResearchStartCases.json")));
  static GameState Prepared(string mode){var s=Game.New(1000,"prepared-research-start-reference");s.Legacy.prepared=true;if(mode!="normal")s.ItemSystemV3=new ItemV3State();s.Credits=s.Data=ScientificNumber.From(1e12);s.Retention.gems=10000;s.Research=Enumerable.Repeat(1,Balance.Research.Length).ToArray();s.Upgrades.purchasedLabs=3;s.Workshop.nodes=mode=="maximum"?new[]{"W06","F02","F03","W10"}:new[]{"W06","F02","F03"};s.Prestige.lab=true;s.Meta.models[Array.FindIndex(MetaBalance.Models,m=>m.Id=="K10")]=0;s=MetaRules.Select(s,"K10");s.Workshop.lastArea="model";string[] types=mode=="none"?Array.Empty<string>():mode=="controller"?new[]{"experiment-controller"}:mode=="protocol"?new[]{"protocol-controller"}:mode=="pair"?new[]{"lab-drone","protocol-controller"}:new[]{"lab-drone","protocol-controller","experiment-controller"};foreach(string type in types){s=RetentionRules.CreateItem(s,type,mode=="maximum"?5:0);var item=s.Workshop.inventory.Last();if(mode=="maximum"){item.level=(int)ItemV3Balance.Get("levelMax");item.forge=(int)ItemV3Balance.Get("forgeMax");}s=Workshop.Equip(s,item.id,Workshop.EquipmentSlot(s,item.id));}if(mode=="unequipped")s.Workshop.equipped=new string[ItemBalance.Slots.Length];return s;}
  static GameState Fund(GameState state,bool pending){var s=state.Copy();var cycle=ScientificNumber.From(1e12);s.Prestige.Total=s.Prestige.Total.Add(cycle.Subtract(s.Prestige.Cycle));s.Prestige.Cycle=cycle;s.Prestige.Free=cycle.Subtract(s.Prestige.Spent);s.Prestige.Entitlement=cycle.Times(pending?2:1);s.Prestige.known=PrestigeBalance.Nodes.Take(30).Select(n=>n.Id).ToArray();s.ItemSystemV3.axiomDiscovered=true;s.ItemSystemV3.axiomDiscoveryAt=1000;return s;}
  static void Near(ScientificNumber actual,NumberData row,string label){var expected=ScientificNumber.FromData(row);if(expected.IsZero)Assert.That(actual.IsZero,Is.True,label);else Assert.That(actual.Log10(),Is.EqualTo(expected.Log10()).Within(2e-10),label);}
  [Test]public void ActualPaidQueueRepeatStartsMinimaSkipAndResetsMatchSource(){var c=Cases();Assert.That(c.sourceHash,Is.EqualTo(ItemV3Balance.SourceHash));Assert.That(c.productionEnabled,Is.False);Assert.That(c.flows.Length,Is.EqualTo(32));foreach(var flow in c.flows){var s=Prepared(flow.mode);foreach(var row in flow.steps){var before=s;string label=flow.name+" "+row.action;switch(row.action){case"manual":case"automatic":s=Game.Research(s,"dataGeneration",row.action);Assert.That(!ReferenceEquals(s,before),Is.EqualTo(row.allowed),label);break;case"queue":s=PrestigeAutomation.QueueResearch(s,"dataGeneration");s=PrestigeAutomation.StartResearchQueue(s);break;case"repeat":s=s.Copy();s.Prestige.researchRepeat=true;s.Prestige.repeatId="dataGeneration";s=PrestigeAutomation.ResearchAuto(s);s.Prestige.researchRepeat=false;break;case"finish":case"age":case"half-second":s=Game.Advance(s,row.at);break;case"unequip":s=s.Copy();s.Workshop.equipped=new string[ItemBalance.Slots.Length];break;case"ready-work":s=s.Copy();foreach(var job in PrestigeAutomation.ResearchJobs(s))job.done=job.required;break;case"settle":Game.SettleResearch(s);break;case"pause":var shadow=Game.New(s.SavedAt);shadow.Challenges.Run=new ChallengeRun{id="no-items",stage=1};shadow.Challenges.Main=s.Copy();ChallengeRules.PauseMain(shadow,row.at);s=shadow.Challenges.Main;break;case"skip":var quote=AdRewards.SkipQuote(s,0);s=AdRewards.BuySkip(s,0,quote.Job,quote.Cost);Assert.That(!ReferenceEquals(s,before),Is.EqualTo(row.allowed),label);break;case"poor":s=s.Copy();s.Data=ScientificNumber.Zero;break;case"prestige":case"axiom":s=Fund(s,row.action=="prestige");var funded=s;s=row.action=="prestige"?PrestigeRules.Reset(s):MetaRules.AxiomReset(s);Assert.That(s,Is.Not.SameAs(funded),label+" actual reset");break;default:Assert.Fail(row.action);break;}Near(s.Credits,row.credits,label+" paid credits");Near(s.Data,row.data,label+" paid data");Assert.That(s.Retention.gems,Is.EqualTo(row.gems),label+" paid Gem skip");Assert.That(s.ItemSystemV3?.automaticResearchStarts??0,Is.EqualTo(row.automaticCount),label+" valid automatic starts");Assert.That(s.Research,Is.EqualTo(row.levels),label+" finished research");Assert.That(s.Prestige.resets,Is.EqualTo(row.prestiges),label);Assert.That(s.Meta.resets,Is.EqualTo(row.axioms),label);var jobs=PrestigeAutomation.ResearchJobs(s).ToArray();Assert.That(jobs.Length,Is.EqualTo(row.jobs.Length),label);foreach(var expected in row.jobs){var actual=jobs.Single(j=>j.id==expected.id);Assert.That(actual.required,Is.EqualTo(expected.required).Within(1e-8),label);Assert.That(actual.done,Is.EqualTo(expected.done).Within(1e-7),label);Assert.That(actual.eventWork,Is.EqualTo(expected.eventWork).Within(1e-7),label+" bonus work");Assert.That(Game.ResearchRemainingSeconds(s,actual),Is.EqualTo(expected.remaining).Within(1e-7),label+" true remaining time");Assert.That(actual.researchStartVersion,Is.EqualTo(expected.version),label);Assert.That(actual.researchStartCause??"",Is.EqualTo(expected.cause),label);Assert.That(actual.previousArea??"",Is.EqualTo(expected.previousArea),label);Assert.That(actual.area??"",Is.EqualTo(expected.area),label);Assert.That(actual.minimumSeconds,Is.EqualTo(expected.minimumSeconds).Within(1e-10),label);Assert.That(actual.minimumUntil,Is.EqualTo(expected.minimumUntil).Within(1e-6),label);Assert.That(actual.startedAt,Is.EqualTo(expected.startedAt).Within(1e-6),label);Assert.That(actual.startingFraction,Is.EqualTo(expected.startingFraction).Within(1e-12),label);Assert.That(actual.automaticOrdinal,Is.EqualTo(expected.automaticOrdinal),label);Assert.That(actual.minimumBypassed,Is.EqualTo(expected.bypassed),label);Assert.That(actual.completionCause??"",Is.EqualTo(expected.completionCause),label);}ItemSystemV3.Validate(s);}}}
  [Test]public void InvalidStartContractAndCauseCannotSpendOrGrant(){var s=Prepared("trio");Assert.Throws<FormatException>(()=>Game.Research(s,"dataGeneration","bogus"));Assert.That(s.Data.CompareTo(ScientificNumber.From(1e12)),Is.Zero);Assert.That(s.ItemSystemV3.automaticResearchStarts,Is.Zero);var paid=Game.Research(s,"dataGeneration");paid.ResearchJob.minimumUntil=double.NaN;Assert.Throws<FormatException>(()=>ItemSystemV3.Validate(paid));}
 }
}
